    async def create_account(
        self,
        *,
        email: str | None = None,
        oidc: CreateAccountRequestOIDC | None = None,
        captcha: str | None = None,
        email_validation_method: CreateAccountRequestEmailValidationMethod
        | None = None,
        origin: CreateAccountRequestOrganizationOrigin | None = None,
        first_name: str | None = None,
        last_name: str | None = None,
    ) -> Account:
        """
        Create a new user request

        Args:
            email: Email of the user. Precisely one of email, oidc can be set.
            oidc: OpenID Connect authentication information that allows a user to
                authenticate through an external identity provider. If this field is
                used, the `email` field must not be set. Precisely one of email, oidc
                can be set.
            captcha: Captcha. Captcha validation code. This is required as an anti-fraud
                measure.
            email_validation_method: In case of account creation by email, we can choose
                to receive a magic_link or an authentication_code by email. By default a
                magic_link will be sent.
            origin: Origin of the organization creation request.
            first_name: First name of the user.
            last_name: Last name of the user.
        """
        data = await self._client.request_json(
            "POST",
            "/account/v3/accounts",
            body={
                "email": email,
                "oidc": oidc,
                "captcha": captcha,
                "email_validation_method": email_validation_method,
                "origin": origin,
                "first_name": first_name,
                "last_name": last_name,
            },
        )
        return Account.model_validate(data)

